<?php
defined('PREVENT_DIRECT_ACCESS') OR exit('No direct script access allowed');
class ProductController extends Controller { private function auth(){if(session_status()!==PHP_SESSION_ACTIVE)session_start();if(empty($_SESSION['product_user']))redirect('login');} private function boot(){$this->call->database();$this->call->model('ProductModel');} private function data(){return ['product_name'=>trim($_POST['product_name']??''),'description'=>trim($_POST['description']??''),'price'=>trim($_POST['price']??''),'quantity'=>trim($_POST['quantity']??'')];} private function ok($d){return $d['product_name']!==''&&is_numeric($d['price'])&&(float)$d['price']>=0&&filter_var($d['quantity'],FILTER_VALIDATE_INT)!==false&&(int)$d['quantity']>=0;} public function index(){$this->auth();$this->boot();$this->call->view('products/index',['products'=>$this->ProductModel->all()]);} public function create(){$this->auth();$this->form([], 'products/create','Add product','');} public function store(){$this->auth();$d=$this->data();if(!$this->ok($d)){$this->form($d,'products/create','Add product','Use valid values.');return;}$this->boot();$this->ProductModel->insert($d);redirect('products');} public function edit($id){$this->auth();$this->boot();$p=$this->ProductModel->find((int)$id);if(!$p)redirect('products');$this->form($p,'products/edit/'.(int)$id,'Edit product','');} public function update($id){$this->auth();$d=$this->data();if(!$this->ok($d)){$this->form($d,'products/edit/'.(int)$id,'Edit product','Use valid values.');return;}$this->boot();$this->ProductModel->update((int)$id,$d);redirect('products');} public function delete($id){$this->auth();$this->boot();$this->ProductModel->delete((int)$id);redirect('products');} private function form($product,$action,$title,$error){$this->call->view('products/form',compact('product','action','title','error'));}}
